// Read-only consistency review of hand-authored receipts; no live collector or application.
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { assessMemoryReceipt, CONTRACT_SHA256 } from './worktrees/task160-initial-counter-order/scripts/loredock-memory-receipts/assess.mjs';

const root = new URL('./worktrees/task160-initial-counter-order/', import.meta.url);
const directory = new URL('docs/fixtures/loredock-initial-counter-order/', root);
const cases = JSON.parse(readFileSync(new URL('cases.json', directory), 'utf8'));
const sha = value => createHash('sha256').update(value).digest('hex');
const assessor = readFileSync(new URL('scripts/loredock-memory-receipts/assess.mjs', root));
assert.equal(sha(assessor), '905fa440ccb4336b9f96948d2f08901b7ea1c8177bf9a31fac06b415099f2382');
assert.equal(sha(readFileSync(new URL('docs/loredock/observable-resource-contract-v2.json', root))), CONTRACT_SHA256);
assert.equal(cases.syntheticOnly, true);
const results = cases.cases.map(item => {
  const raw = readFileSync(new URL(item.path, directory), 'utf8');
  const result = assessMemoryReceipt(raw, cases.binding);
  assert.equal(result.status, item.expectedStatus, item.id);
  for (const code of item.requiredReasonCodes) assert(result.reasons.some(row => row.code === code), item.id + ':' + code);
  assert.equal(result.offlineOnly, true);
  assert.equal(result.resourceQualification, false);
  return { id: item.id, receiptSha256: sha(raw), bytes: Buffer.byteLength(raw), ...result };
});
console.log(JSON.stringify({ schemaVersion: 'loredock-initial-counter-order-review-results/1',
  syntheticOnly: true, liveProbeExecuted: false, assessorSha256: sha(assessor), contractSha256: CONTRACT_SHA256,
  checkedCases: results.length, failures: 0, results }, null, 2));
